-- Run after companion-table inheritance.
SELECT 'BUILDING_ROULS_SOMATIC_LATTICE', 'YIELD_SCIENCE', 0
 WHERE NOT EXISTS (SELECT 1 FROM Building_YieldChanges
 WHERE BuildingType = 'BUILDING_ROULS_SOMATIC_LATTICE' AND YieldType = 'YIELD_SCIENCE');
SELECT 'BUILDING_ROULS_SOMATIC_LATTICE', 'YIELD_PRODUCTION', 0
 WHERE NOT EXISTS (SELECT 1 FROM Building_YieldChanges
 WHERE BuildingType = 'BUILDING_ROULS_SOMATIC_LATTICE' AND YieldType = 'YIELD_PRODUCTION');
UPDATE Building_YieldChanges SET Yield = Yield + 2
 WHERE BuildingType = 'BUILDING_ROULS_SOMATIC_LATTICE' AND YieldType IN ('YIELD_SCIENCE', 'YIELD_PRODUCTION');

-- Buddy has no ranged-only, anti-submarine, interception, resource or upgrade
-- rows from its visual model. It is a Biology-era naval melee support unit.
 SELECT 'UNIT_ROULS_BUDDY', SelectionSound, FirstSelectionSound
 FROM UnitGameplay2DScripts WHERE UnitType = 'UNIT_BATTLESHIP';

 SELECT 'LEADER_TRENT_ROULS', Type,
 CASE Type
 WHEN 'FLAVOR_OFFENSE' THEN 8 WHEN 'FLAVOR_DEFENSE' THEN 8
 WHEN 'FLAVOR_CITY_DEFENSE' THEN 7 WHEN 'FLAVOR_MILITARY_TRAINING' THEN 9
 WHEN 'FLAVOR_SCIENCE' THEN 9 WHEN 'FLAVOR_SPACESHIP' THEN 8
 WHEN 'FLAVOR_NAVAL' THEN 7 WHEN 'FLAVOR_NAVAL_RECON' THEN 7
 WHEN 'FLAVOR_NAVAL_GROWTH' THEN 6 WHEN 'FLAVOR_NAVAL_TILE_IMPROVEMENT' THEN 6
 WHEN 'FLAVOR_RANGED' THEN 7 WHEN 'FLAVOR_MOBILE' THEN 6
 WHEN 'FLAVOR_PRODUCTION' THEN 7 WHEN 'FLAVOR_GROWTH' THEN 6
 WHEN 'FLAVOR_EXPANSION' THEN 5 WHEN 'FLAVOR_DIPLOMACY' THEN 5
 WHEN 'FLAVOR_WONDER' THEN 2 WHEN 'FLAVOR_CULTURE' THEN 3
 WHEN 'FLAVOR_ARCHAEOLOGY' THEN 2 WHEN 'FLAVOR_RELIGION' THEN 1
 ELSE 5 END FROM Flavors;
 SELECT 'LEADER_TRENT_ROULS', MajorCivApproachType,
 CASE MajorCivApproachType WHEN 'MAJOR_CIV_APPROACH_WAR' THEN 7
 WHEN 'MAJOR_CIV_APPROACH_AFRAID' THEN 2 WHEN 'MAJOR_CIV_APPROACH_GUARDED' THEN 6
 ELSE 5 END FROM Leader_MajorCivApproachBiases WHERE LeaderType = 'LEADER_WASHINGTON';
 SELECT 'LEADER_TRENT_ROULS', MinorCivApproachType, Bias
 FROM Leader_MinorCivApproachBiases WHERE LeaderType = 'LEADER_WASHINGTON';
-- Preserve complete generic diplomatic coverage; specific voice appears below.
 SELECT 'LEADER_TRENT_ROULS', ResponseType, Response, Bias
 FROM Diplomacy_Responses WHERE LeaderType = 'LEADER_WASHINGTON';

